def max_len(a: list[int], k: int) -> int:
    first = {0: -1}
    s = best = 0
    for i, x in enumerate(a):
        s += x
        if s - k in first:
            best = max(best, i - first[s - k])
        if s not in first:
            first[s] = i
    return best

int subarraySum(const std::vector<int>& a, int k) {
    std::unordered_map<long long, int> seen;
    seen[0] = 1;
    long long s = 0;
    int res = 0;
    for (int x : a) {
        s += x;
        auto it = seen.find(s - k);
        if (it != seen.end()) res += it->second;
        seen[s]++;
    }
    return res;
}

int waysToSplitArray(const std::vector<int>& a) {
    long long total = 0;
    for (int x : a) total += x;
    long long left = 0;
    int ways = 0;
    for (size_t i = 0; i + 1 < a.size(); i++) {
        left += a[i];
        if (left >= total - left) ways++;
    }
    return ways;
}

int findMaxLength(const std::vector<int>& a) {
    int n = (int)a.size();
    std::vector<int> first(2 * n + 1, -2);  // -2 = not seen yet
    first[n] = -1;                           // balance 0 before index 0
    int bal = 0, best = 0;
    for (int i = 0; i < n; i++) {
        bal += a[i] == 1 ? 1 : -1;
        int& f = first[bal + n];
        if (f == -2) f = i;
        else best = std::max(best, i - f);
    }
    return best;
}

