int pivotIndex(const std::vector<int>& a) {
    long long total = 0;
    for (int x : a) total += x;
    long long left = 0;
    for (int i = 0; i < (int)a.size(); i++) {
        if (left == total - left - a[i]) return i;
        left += a[i];
    }
    return -1;
}

def check_subarray_sum(a, k):
    first = {0: -1}        # remainder -> earliest prefix index
    s = 0
    for i, x in enumerate(a):
        s = (s + x) % k
        if s in first:
            if i - first[s] >= 2:
                return True
        else:
            first[s] = i
    return False

int numSubmatrixSumTarget(std::vector<std::vector<int>> M, int target) {
    if (M.empty() || M[0].empty()) return 0;
    int R = M.size(), C = M[0].size();
    if (R > C) {  // fix pairs along the shorter side
        std::vector<std::vector<int>> T(C, std::vector<int>(R));
        for (int i = 0; i < R; i++)
            for (int j = 0; j < C; j++) T[j][i] = M[i][j];
        M.swap(T);
        std::swap(R, C);
    }
    int res = 0;
    std::vector<long long> col(C);
    std::unordered_map<long long, int> cnt;
    for (int top = 0; top < R; top++) {
        std::fill(col.begin(), col.end(), 0);
        for (int bot = top; bot < R; bot++) {
            for (int c = 0; c < C; c++) col[c] += M[bot][c];
            cnt.clear();
            cnt[0] = 1;
            long long s = 0;
            for (int c = 0; c < C; c++) {
                s += col[c];
                auto it = cnt.find(s - target);
                if (it != cnt.end()) res += it->second;
                cnt[s]++;
            }
        }
    }
    return res;
}

def most_covered_point(intervals, M):
    if not intervals:
        return None
    diff = [0] * (2 * M + 2)          # index = coordinate + M
    for a, b in intervals:
        diff[a + M] += 1
        diff[b + M + 1] -= 1          # closed interval: stop after b
    best_x, best, cur = None, -1, 0
    for i in range(2 * M + 1):
        cur += diff[i]
        if cur > best:
            best, best_x = cur, i - M
    return best_x

