class OnesCounter {
    std::vector<std::uint64_t> P_;    // P_[i] = ones in bits[0 .. i-1]
public:
    explicit OnesCounter(const std::vector<std::uint8_t>& bits) : P_(bits.size() + 1, 0) {
        for (std::size_t i = 0; i < bits.size(); ++i)
            P_[i + 1] = P_[i] + bits[i];
    }
    std::uint64_t countOnes(std::size_t l, std::size_t r) const {
        return P_[r + 1] - P_[l];
    }
};

