#include <vector>
#include <algorithm>

int longestAtMostK(const std::vector<int>& a, long long K) {
    int n = a.size();
    std::vector<long long> P(n + 1, 0), M(n + 1, 0);
    for (int i = 0; i < n; ++i) P[i + 1] = P[i] + a[i];
    M[0] = P[0];
    for (int i = 1; i <= n; ++i) M[i] = std::max(M[i - 1], P[i]);   // non-decreasing
    int best = 0;
    for (int j = 1; j <= n; ++j) {
        // smallest i < j with P[i] >= P[j] - K  <=>  first i with M[i] >= P[j] - K
        int i = std::lower_bound(M.begin(), M.begin() + j, P[j] - K) - M.begin();
        if (i < j) best = std::max(best, j - i);
    }
    return best;
}

def available_days(num_days, num_people, blocks, p):
    by_person = {}
    for person, s, e in blocks:
        by_person.setdefault(person, []).append((s, e))
    diff = [0] * (num_days + 2)
    for spans in by_person.values():           # merge per person: count a person once per day
        spans.sort()
        merged = []
        for s, e in spans:
            if merged and s <= merged[-1][1] + 1:
                merged[-1][1] = max(merged[-1][1], e)
            else:
                merged.append([s, e])
        for s, e in merged:
            diff[s] += 1
            diff[e + 1] -= 1
    result, busy = [], 0
    for day in range(1, num_days + 1):
        busy += diff[day]                      # prefix sum = people busy today
        if num_people - busy >= p:
            result.append(day)
    return result

long long minCost(vector<long long> h) {
    sort(h.begin(), h.end());
    int n = h.size();
    long long total = accumulate(h.begin(), h.end(), 0LL), below = 0, best = total;
    for (int i = 0; i < n; ++i) {
        if (i == 0 || h[i] != h[i - 1]) {
            long long cost = below + (total - below) - (long long)(n - i) * h[i];
            best = min(best, cost);
        }
        below += h[i];
    }
    return best;
}
